package dev.ambivalenton.openv.data.model

data class AppGlossaryEntry(val id: String, val titleKey: String, val descriptionKey: String, val categoryKey: String)

val appGlossary: List<AppGlossaryEntry> = listOf(
    AppGlossaryEntry("overview","Übersicht","Dein nächster Weg, als lesbarer Satz oder kompakte Infokarte. Die Übersicht zeigt Verbindungen zu sichtbaren Favoriten und berücksichtigt ihre Linien und Zeitregeln.","Erste Schritte"),
    AppGlossaryEntry("search","Suchen","Hier planst du einen Weg mit Start, Ziel, Zeit und Verkehrsmitteln. Auch dein Favoriten-Netzplan, Vormerkungen und frühere Suchen sind hier zu Hause.","Erste Schritte"),
    AppGlossaryEntry("origin","Startpunkt","Der Ort, an dem die Suche beginnt. Das kann deine Geräteposition, ein manuell gewählter Ort oder ein bewusst als Start gesetzter Favorit sein.","Erste Schritte"),
    AppGlossaryEntry("destination","Ziel","Dorthin möchtest du. Ein Ziel kann eine Haltestelle, eine Adresse oder ein gespeicherter Favorit sein. Ein gefundener Ort garantiert noch keine Verbindung.","Erste Schritte"),
    AppGlossaryEntry("stop","Haltestelle","Ein Ort zum Ein-, Aus- oder Umsteigen. Dazu zählen auch Bahnhöfe. Ein Eintrag im lokalen Verzeichnis enthält keinen aktuellen Fahrplan.","Erste Schritte"),
    AppGlossaryEntry("journey","Verbindung","Der gesamte vorgeschlagene Weg zum Ziel. Er kann mehrere Fahrten, Fußwege und Umstiege enthalten. Eine Fahrt ist dagegen ein einzelner Fahrzeugabschnitt.","Erste Schritte"),
    AppGlossaryEntry("favourite","Favorit","Ein Ort mit deinem Namen, Symbol und deiner Farbe. Du kannst ihn in den Netzplan setzen und mit Zeitregeln und Verkehrsfiltern versehen.","Dein Netz"),
    AppGlossaryEntry("network","Netzplan","Deine Favoriten werden zu Stationen, deine Verknüpfungen zu Linien. Das ist dein persönliches Wegenetz, kein offizieller Linienplan. Bei einer passenden angepinnten Verbindung zeigt ein Verkehrsmittel den Fortschritt des Assistenten. Sonst sind die kleinen Fahrzeuge dekorativ.","Dein Netz"),
    AppGlossaryEntry("network_line","Linie im Netzplan","Verbindet zwei Favoriten. Beim Antippen wird zwischen ihnen gesucht. Im Bearbeiten-Modus legst du eine oder beide Suchrichtungen fest. Gemeint ist keine tatsächliche Bus- oder Bahnlinie.","Dein Netz"),
    AppGlossaryEntry("transfer_point","Umstiegspunkt","Ein Favorit, der im Netzplan auf dem Weg zu einem anderen Ziel liegt, etwa dein Bahnhof. Die Übersicht kann über ihn weiterplanen, statt ihn als Endziel zu behandeln.","Dein Netz"),
    AppGlossaryEntry("tray","Ablage","Hier warten Favoriten, die noch keinen Platz im Raster haben. Unter Bearbeiten wählst du einen aus und tippst auf ein freies Rasterfeld.","Dein Netz"),
    AppGlossaryEntry("virtual_start","Favorit als Start","Wähle unter Favoriten-Einstellungen → Raster des Netzplans die Halte-Aktion Als aktuellen Standort festlegen. Halte danach einen Favoriten, um ab dort zu planen; erneutes Halten hebt die Auswahl auf. Dein tatsächlicher Gerätestandort wird dadurch nicht verändert.","Dein Netz"),
    AppGlossaryEntry("favourite_radius","Favoriten-Umkreis","Legt fest, wie nah du einem Favoriten sein musst, damit die App ab dort plant. Möglich sind auch Aus oder immer der nächstgelegene Favorit. Entfernung allein bestätigt keinen Bahnsteig.","Dein Netz"),
    AppGlossaryEntry("rule","Zeitregel","Hebt Favoriten oder Linien zu passenden Zeiten hervor; Linien lassen sich zeitweise ausblenden. Ein zeitabhängiger Standort hilft ohne GPS und ohne manuellen Start. Hervorgehobene Wege haben in der Übersicht Vorrang.","Dein Netz"),
    AppGlossaryEntry("chart","Balkendiagramm","Verbindungen nebeneinander vergleichen, ohne Zeiten zusammenzurechnen: Jede Zeile ist ein Weg, die Abschnitte stehen für Verkehrsmittel und Gehwege. Antippen öffnet die Details.","Unterwegs"),
    AppGlossaryEntry("timeline","Zeitstrahl","Die Reihenfolge einer einzelnen Verbindung: losgehen, einsteigen, umsteigen, ankommen. Hier findest du verfügbare Halte, Zeiten, Gleise und Gehhinweise.","Unterwegs"),
    AppGlossaryEntry("intermediate_stop","Zwischenhalt","Ein Halt, den dein Fahrzeug auf seiner Fahrt anfährt. Du bleibst dabei normalerweise sitzen. Nicht zu verwechseln mit einem selbst gewählten Zwischenstopp.","Unterwegs"),
    AppGlossaryEntry("waypoint","Zwischenstopp","Ein zusätzlicher Ort, den du selbst in deine Reise aufnimmst, etwa die Bäckerei vor der Arbeit. Eine Aufenthaltsdauer lässt sich mitplanen.","Unterwegs"),
    AppGlossaryEntry("transfer","Umstieg","Du wechselst das Fahrzeug. Dafür können Wartezeit, ein Fußweg und ein anderer Bahnsteig nötig sein. Prognosen und dein Gehtempo beeinflussen, ob der Anschluss erreichbar erscheint.","Unterwegs"),
    AppGlossaryEntry("companion","Reisebegleiter","Begleitet deine angepinnte Verbindung mit nächstem Halt, Umstieg, Ankunft und Alternativen. Er startet durch Anpinnen und bleibt bei minimierter Ansicht aktiv, soweit Android es zulässt.","Unterwegs"),
    AppGlossaryEntry("pin","Anpinnen","Startet die aktive Begleitung einer Verbindung. Es ist mehr als eine Vormerkung und legt keinen Favoriten an. Bestätigtes Entfernen auf der Reisekarte beendet die Begleitung.","Unterwegs"),
    AppGlossaryEntry("saved_journey","Vormerkung","Ein Weg auf deiner Merkliste unter Suchen, ohne laufende Begleitung. Halte den Pin gedrückt, um ihn zu speichern. Die Vormerkung endet mit der bekannten Abfahrt oder deiner Löschung.","Unterwegs"),
    AppGlossaryEntry("bubble","Schwebende Reisekarte","Zeigt deine nächste Abfahrt, auch wenn du eine andere App geöffnet hast. Sie zeigt die bereits angepinnte Reise und braucht Androids Erlaubnis zum Einblenden. Schließen blendet nur die Karte aus; die Reise bleibt angepinnt.","Unterwegs"),
    AppGlossaryEntry("alternative_suggestions","Alternative Fahrten vorschlagen","Zeigt bessere erreichbare Verbindungen kurz vor dem Start und unterwegs als Vergleich. Der Schalter steuert automatische Pop-ups; die Alternativen im angepinnten Zeitstrahl bleiben erreichbar.","Unterwegs"),
    AppGlossaryEntry("walking_pace","Dein Gehtempo","Damit passt Öpen-V die Gehzeitprüfung bei Suche und Umstiegen an dich an. Optional schlägt lokales Lernen ein Tempo vor. Erst dein Antippen übernimmt den Vorschlag.","Unterwegs"),
    AppGlossaryEntry("ignore_walking","Gehzeiten ignorieren","Blendet Fußwege aus Balken und Zeitstrahlen aus und lockert die Gehzeitprüfung. Dadurch können praktisch nicht erreichbare Umstiege erscheinen. Der tatsächliche Weg bleibt bestehen.","Unterwegs"),
    AppGlossaryEntry("departures","Abfahrten","Die nächsten Fahrten ab einer Haltestelle, mit Linie, Richtung und Zeit. Abfahrten sind keine vollständige Verbindung bis zu einem Ziel.","Unterwegs"),
    AppGlossaryEntry("board","Anzeigetafel","Deine Abfahrtsanzeige im gewählten Design. Die Haltestellen-Liste enthält Favoritenorte und eigene Einträge. Entfernen aus der Tafel löscht keinen Favoriten. Nächstgelegene nutzt den verfügbaren Standort.","Unterwegs"),
    AppGlossaryEntry("forecast","Fahrplanprognose","Eine Einschätzung anhand der Zeiten des Fahrplandienstes. Sie ist kein gemessener Standort und bestätigt weder Einstieg noch Ausstieg.","Daten & Standort"),
    AppGlossaryEntry("realtime","Echtzeit","Aktualisierte Angaben eines Anbieters, etwa eine erwartete Abfahrt oder ein Ausfall. Auch Echtzeit kann fehlen oder veraltet sein. Keine Meldung bedeutet nicht automatisch pünktlich.","Daten & Standort"),
    AppGlossaryEntry("scheduled","Sollzeit","Die im Fahrplan vorgesehene Zeit. Sie bleibt von einer aktuellen Prognose oder einer lokalen Schätzung zu unterscheiden.","Daten & Standort"),
    AppGlossaryEntry("gps","GPS-Standort","Eine vom Gerät gemessene Position. Sie kann ungenau sein oder ausbleiben. Der Reisebegleiter nutzt brauchbare Messungen für den Fortschritt, aber nicht als Beweis für den richtigen Bahnsteig.","Daten & Standort"),
    AppGlossaryEntry("stop_directory","Lokales Haltestellenverzeichnis","Mitgelieferte öffentliche Haltestellendaten für schnelle Vorschläge, auch offline. Das Verzeichnis enthält keinen vollständigen Fahrplan und öffnet keinen DELFI-Navi-Zugang.","Daten & Standort"),
    AppGlossaryEntry("provider","Fahrplandienst","Der Server, der Verbindungen und Abfahrten liefert. Öpen-V verwendet VRR OpenService mit Schwerpunkt Rhein-Ruhr. Abdeckung und Echtzeit hängen vom Datenbestand ab.","Daten & Standort"),
    AppGlossaryEntry("search_history","Suchverlauf","Frühere Suchwege und kurzzeitig gespeicherte Ergebnisse auf deinem Gerät. Unter Info & Hilfe → Dienste & Daten kannst du den Verlauf löschen; dabei werden auch zugehörige Reise-Zwischenspeicher geleert.","Daten & Standort"),
    AppGlossaryEntry("backup","Export / Import","Sichert deinen gespeicherten Bestand als lesbare JSON-Datei oder stellt ihn wieder her. Die Datei ist unverschlüsselt und kann persönliche Orte enthalten. Import ersetzt nach Bestätigung die bisherigen Daten.","Daten & Standort"),
    AppGlossaryEntry("open_source","Open Source","Der App-Code steht unter GPL-3.0-or-later: ansehen, verändern und unter den Lizenzbedingungen weitergeben. Fremde Daten, Schriften und Server haben eigene Lizenzen oder Nutzungsbedingungen.","Daten & Standort"),
    AppGlossaryEntry("design","App-Design","Bestimmt Farben, Flächen, Formen und Motive. Anzeigetafel, Balkendiagramm und Netzplan haben eigene Optionen. App-Theme lässt unterstützte Bereiche dem aktuellen App-Design folgen.","Deine Ansicht"),
    AppGlossaryEntry("personal_theme","Persönliches Theme","Dein gespeichertes Gesamtbild mit Designeinstellungen und App-Logo. Mit der Diskette speichern, später aus der eigenen Liste anwenden oder löschen.","Deine Ansicht"),
    AppGlossaryEntry("font","Schriftart","Die Schrift für die App und ihre Übersicht. Die mitgelieferten Schriften funktionieren ohne Download. Größe und Lesbarkeit passt du separat an.","Deine Ansicht"),
    AppGlossaryEntry("overview_cards","Kartenansicht","Zeigt dieselben gewählten Angaben der Übersicht als Infokarten. Hier sind Karten mit Text gemeint, keine Straßenkarte.","Deine Ansicht"),
    AppGlossaryEntry("quote_design","Infotext-Design","Rahmen und Hintergrund für Sprüche und Fakten. Ein anderer Rahmen ändert die Gestaltung, während Textwechsel und Chronik erhalten bleiben.","Deine Ansicht"),
    AppGlossaryEntry("bar_chart_design","Balkendiagramm-Design","Gestaltet Balken, Linien, Beschriftungen und Fußabdrücke. App-Theme folgt deinem App-Design; eigenständige Designs behalten ihre eigene Gestaltung.","Deine Ansicht"),
    AppGlossaryEntry("prints","Fußabdrücke","Bewegte Abdrücke für Gehabschnitte. Stil, Tempo und Größe lassen sich einstellen. Fußabdruck-Größe gilt für Balkendiagramm und Zeitstrahl sowie die Ersatzpunkte. Im Zeitstrahl verlaufen die Abdrücke immer gerade.","Deine Ansicht"),
    AppGlossaryEntry("text_history","Textchronik","Dein Lesetagebuch mit bereits gezeigten Fakten, Gedanken, Haikus, Satiren und Bedienungstipps. Halte den Infotext gedrückt, um es zu öffnen. Alles bleibt auf dem Gerät.","Deine Ansicht"),
    AppGlossaryEntry("widget","Widget","Ein kleines Stück Öpen-V auf deinem Android-Startbildschirm: Favoriten oder Abfahrten. Der Launcher bestimmt mögliche Größen; Android kann Aktualisierungen verzögern.","Deine Ansicht"),
    AppGlossaryEntry("modes_extras","Modi & Verhalten","Schwarz/Weiß, Ruhemodus, Stromsparmodus und Minimalismus, Tag & Nacht, die schwebende Reisekarte der angepinnten Fahrt, die Langdruck-Aktion im Balkendiagramm sowie Sichern & Übertragen – jede Einstellung in einem eigenen Rahmen.","Deine Ansicht"),
    AppGlossaryEntry("quiet","Ruhemodus","Weniger Bewegung, ein eigenes gespeichertes Design. Ideal, wenn du die App ruhiger lesen möchtest.","Deine Ansicht"),
    AppGlossaryEntry("monochrome","Schwarz/Weiß","Zeigt App-Farben in Graustufen. Deine gespeicherten Farben und Themes bleiben erhalten.","Deine Ansicht"),
    AppGlossaryEntry("power_saving","Stromsparmodus","Reduziert Effekte und Abfragen. Der Reisebegleiter folgt Anbieterzeiten; gelegentliche Standortprüfungen suchen nur nach Abweichungen. GPS-bestätigte Ein- und Ausstiegsaussagen sind dabei ausgesetzt.","Deine Ansicht"),
    AppGlossaryEntry("minimalism","Minimalismus-Modus","Blendet Infotext und zusätzliche Suchbereiche aus und gibt der Anzeigetafel den verfügbaren Platz. Die gespeicherten Inhalte bleiben erhalten.","Deine Ansicht"),
    AppGlossaryEntry("chart_long_press","Balken gedrückt halten","Du wählst die Aktion selbst: nichts tun, Kompaktansicht öffnen, vormerken, anpinnen oder Zwischenstopp hinzufügen. Ein kurzer Tipp öffnet weiterhin den Zeitstrahl.","Deine Ansicht"),
    AppGlossaryEntry("compact_view","Kompaktansicht","Zeigt eine Verbindung oder die Live-Verbindung als kompakte Karte im Vollbild, mit Datenquelle und Stand. Öpen-V erstellt dabei kein Bild und teilt nichts; ein Bildschirmfoto machst nur du, wenn du möchtest.","Deine Ansicht"),
)
